def verify_oia028() -> None:
    if not OIA028.exists():
        raise RuntimeError(f"Actual OIA-028 production module missing: {OIA028}")
    source = OIA028.read_text(encoding="utf-8")
    required = [
        'SCHEMA_VERSION = "OIA-028"', 'ENGINE_ID = "OIA-028"', 'EVIDENCE_BATCH_POLICY_ID',
        'EVIDENCE_BATCH_ISSUED', 'EVIDENCE_BATCH_ENTRY_AUTHORIZED', 'evidence_batch_hash',
        'batch_entry_hash', 'source_evidence_session_hash', 'source_evidence_manifest_hash',
        'source_certification_hash', 'source_readiness_hash', 'source_session_hash', 'source_activation_hash',
        'source_claim_hash', 'source_dispatch_manifest_hash', 'source_batch_hash', 'authorized_evidence_operations',
        'prohibited_operations', 'read_only_corpus', 'evidence_collection_allowed', 'research_execution_allowed',
        'analytic_conclusion_allowed', 'forecast_creation_allowed', 'qseries_handoff_allowed',
        'market_order_creation_allowed', 'funds_movement_allowed', 'portfolio_mutation_allowed',
    ]
    missing = [token for token in required if token not in source]
    if missing:
        raise RuntimeError(f"Actual OIA-028 production contract mismatch: {missing}")

def write_full_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source.rstrip() + "\n", encoding="utf-8")
    print(f"[OK] FULL REPLACEMENT: {path}")

def update_init() -> None:
    source = INIT.read_text(encoding="utf-8") if INIT.exists() else "__all__ = []\n"
    marker = "from .oracle_certified_research_evidence_collection_batch_activation_gate import ("
    if marker not in source:
        source = source.rstrip() + "\n" + INIT_BLOCK
        INIT.write_text(source.rstrip() + "\n", encoding="utf-8")
        print(f"[OK] PACKAGE UPDATED: {INIT}")
    else:
        print(f"[OK] PACKAGE ALREADY CURRENT: {INIT}")

def main() -> int:
    print("=" * 40)
    print(" OIA-029 INSTALLER")
    print(" EVIDENCE COLLECTION BATCH ACTIVATION")
    print(" READ-ONLY COLLECTION AUTHORITY BOUNDARY")
    print("=" * 40)
    verify_oia028()
    print("[OK] Actual OIA-028 evidence batch contract verified")
    write_full_replacement(PRODUCTION, PRODUCTION_SOURCE)
    write_full_replacement(TEST, TEST_SOURCE)
    update_init()
    py_compile.compile(str(PRODUCTION), doraise=True)
    py_compile.compile(str(TEST), doraise=True)
    py_compile.compile(str(INIT), doraise=True)
    print("[OK] Production, test, and package syntax verified")
    result = subprocess.run([sys.executable, str(TEST)], cwd=str(ROOT), check=False)
    if result.returncode != 0:
        raise SystemExit(result.returncode)
    print("[OK] OIA-029 test executed automatically")
    print()
    print("[DONE] OIA-029 evidence collection batch activation gate installed")
